return allHits.map(hit => ({ json: hit }));

// Normaliza + sanitiza titulos. Sale con externalId, licenseType mapeado, imageUrl, tags, sourceUrl.
const LICENSE_MAP = {
  'BY': 'CC-BY', 'BY-SA': 'CC-BY-SA', 'BY-NC': 'CC-BY-NC', 'BY-NC-SA': 'CC-BY-NC',
  'BY-ND': 'CC-BY', 'BY-NC-ND': 'CC-BY-NC', 'CC0': 'CC0',
  'Standard Digital File License': 'commercial',
};
const PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*easy\s*(to\s*)?print(ing)?\b/gi,
  /\|?\s*no\s*supports?\b/gi,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
];
function cleanTitle(t) {
  if (!t) return 'Sin titulo';
  let out = String(t);
  for (const p of PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—-—]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : 'Sin titulo';
}
return $input.all().map(({ json: d }) => {
  const rawLicense = (d.license || '').trim();
  const licenseType = LICENSE_MAP[rawLicense] || 'unknown';
  const author = d.designCreator?.name || 'Unknown';
  const externalId = String(d.id ?? '');
  const slug = d.slug || externalId;
  return {
    json: {
      externalId,
      source: 'MAKERWORLD',
      sourceUrl: `https://makerworld.com/en/models/${slug}`,
      title: cleanTitle(d.titleTranslated || d.title),
      description: '',
      imageUrl: d.cover || d.coverPortrait || null,
      licenseType,
      licenseAttribution: `${author} — via MakerWorld`,
      category: (Array.isArray(d.tags) && d.tags[0]) || null,
      tags: Array.isArray(d.tags) ? d.tags.slice(0, 15) : [],
      trendScore: Math.round(d.hotScore ?? d.likeCount ?? 0),
      provider: 'LOCAL',
    },
  };
});

// Suma TODOS los plates de cada instance → variante. Sanitiza nombre de variante. priceFrom = min.
const FILAMENT_PRICE_PER_KG = 400, WASTE_PCT = 5, KWH_PRICE = 4.5, WATTS = 100, MARGIN_PCT = 300;
const VARIANT_PATTERNS = [
  /\|?\s*(no |sin )?(ams|supports?|soportes?)\b/gi,
  /\|?\s*\d+\.?\d*mm\s*layer\b.*$/i,
  /\|?\s*\d+\s*walls?\b.*$/i,
  /\|?\s*\d+%\s*infill\b.*$/i,
  /\|?\s*免支撑\S*/g,
  /\|?\s*多色一盘\S*/g,
  /\|?\s*参数优化\S*/g,
  /\|?\s*模型优化\S*/g,
];
function cleanVariantName(t, idx) {
  if (!t) return `Variante ${idx + 1}`;
  let out = String(t);
  for (const p of VARIANT_PATTERNS) out = out.replace(p, '');
  out = out.replace(/\s*[|·—–-]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  return out.length >= 3 ? out : `Variante ${idx + 1}`;
}
function priceForPlates(plates) {
  const grams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
  const seconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
  const hours = seconds / 3600;
  if (grams <= 0 || hours <= 0) return null;
  const effectiveGrams = grams * (1 + WASTE_PCT / 100);
  const filament = (effectiveGrams / 1000) * FILAMENT_PRICE_PER_KG;
  const electricity = hours * (WATTS / 1000) * KWH_PRICE;
  const subtotal = filament + electricity;
  return { grams, hours: Number(hours.toFixed(2)), price: Math.round(subtotal * (1 + MARGIN_PCT / 100)) };
}
return $input.all().map((item) => {
  const htmlStr = item.json?.solution?.response || "";
  const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
  let rawJson = match ? match[1] : htmlStr;
  rawJson = rawJson.replace(/<[^>]*>?/gm, '');

  let json = {};
  try { json = JSON.parse(rawJson); } catch (e) {}

  const instances = json?.instances || [];
  const designExtension = json?.designExtension || {};
  const designPics = Array.isArray(designExtension?.design_pictures) ? designExtension.design_pictures.map(p => p.url).filter(Boolean) : [];
  const cover = json?.cover;
  let images = cover ? [cover, ...designPics.filter(u => u !== cover)] : designPics;
  variantsRaw.forEach(v => {
    if (v.imageUrl && !images.includes(v.imageUrl)) {
        images.push(v.imageUrl);
    }
  });

  const variantsRaw = instances.map((ins, i) => {
    const plates = (((ins.extention) || {}).modelInfo || {}).plates || [];
    const calc = priceForPlates(plates);
    if (!calc) return null;
    const insImg = (ins.extention && ins.extention.modelInfo && ins.extention.modelInfo.image) || ins.image || ins.cover || ins.picture;
    return { name: cleanVariantName(ins.title || ins.titleTranslated, i), grams: calc.grams, hours: calc.hours, price: calc.price, imageUrl: insImg };
  }).filter(Boolean);

  const variants = variantsRaw.sort((a, b) => a.price - b.price);
  const priceFrom = variants.length ? variants[0].price : null;
  const description = (json?.summaryTranslated || json?.summary || '').slice(0, 2000);

  return {
    json: {
      __detail: {
        id: json?.id,
        images,
        description,
        variants,
        priceFrom,
      },
    },
  };
});

const normalized = $('Drop unknown licenses').all();
const stripHtml = (html) => String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, 2000);

const products = [];
for (const item of items) {
    const det = item?.json?.__detail;
    if (!det || !det.id) continue;

    // Cruce seguro por ID en vez de por indice
    const nItem = normalized.find(x => String(x.json.externalId) === String(det.id));
    if (!nItem) continue;

    const n = nItem.json;
    products.push({
        ...n,
        description: stripHtml(det.description),
        descriptionHtml: det.description || '',
        images: det.images || [],
        variants: det.variants || [],
        priceFrom: det.priceFrom ?? null,
        price: det.priceFrom ?? null,
    });
}

const chunks = [];
const BATCH_SIZE = 15;
for (let i = 0; i < products.length; i += BATCH_SIZE) {
    chunks.push({ json: { products: products.slice(i, i + BATCH_SIZE) } });
}
return chunks;

// Llama a Gemini API para enriquecer los productos
const products = $input.all()[0].json.products;

// Reemplaza esto con tu API Key real de Google Gemini
const GEMINI_API_KEY = $env.GEMINI_API_KEY || "TU_API_KEY_AQUI"; 
const GEMINI_URL = "https://generativelanguage.googleapis.com/v1beta/models/gemini-3-flash-preview:generateContent?key=" + GEMINI_API_KEY.trim();


    let cookieString = "";
    try {
        const cookies = $("MakerWorld: search").first().json.solution.cookies || [];
        cookieString = cookies.map(c => `${c.name}=${c.value}`).join("; ");
    } catch(e) {}

for (let i = 0; i < products.length; i++) {
    const p = products[i];
    if (!p.title) continue;
    if (GEMINI_API_KEY.includes("TU_API_KEY_AQUI") || GEMINI_API_KEY.trim() === "") {
        p.description = "ERROR: OLVIDASTE PONER TU API KEY DE GEMINI EN EL NODO DE CODIGO!";
        continue;
    }


    let base64Image = null;
    try {
        let mimeType = 'image/jpeg';
        const imgUrl = (p.images && p.images.length > 0) ? p.images[0] : p.imageUrl;

        if (imgUrl) {
            try {
                // Descargamos la imagen como Buffer binario para mandarla a Gemini
                const imgBuffer = await this.helpers.httpRequest({
                    method: 'GET',
                    url: imgUrl,
                    encoding: null,
                    responseType: 'arraybuffer',
                    timeout: 5000,
                    headers: {
                        'User-Agent': flareUserAgent,
                        'Accept': 'image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8',
                        'Accept-Language': 'en-US,en;q=0.9',
                        'Sec-Fetch-Dest': 'image',
                        'Sec-Fetch-Mode': 'no-cors',
                        'Sec-Fetch-Site': 'cross-site',
                        'Referer': 'https://makerworld.com/',
                        'Cookie': cookieString
                    }
                });
                if (imgBuffer && imgBuffer.length > 500) {
                    // Check magic bytes to prevent sending WEBP as JPEG (causes Gemini 400 Bad Request)
                    const header = imgBuffer.slice(0, 4).toString("hex").toUpperCase();
                    if (header.startsWith("89504E47")) mimeType = "image/png";
                    else if (header.startsWith("52494646")) mimeType = "image/webp";
                    else if (header.startsWith("FFD8FF")) mimeType = "image/jpeg";
                    else {
                        throw new Error("Makerworld blocked the image or returned an invalid format. Magic bytes: " + header);
                    }
                    base64Image = Buffer.from(imgBuffer).toString("base64");
                } else {
                    throw new Error("Imagen vacia o bloqueada por Makerworld");
                }
            } catch (imgErr) {
                console.log("Error descargando imagen para Gemini:", imgErr.message);
            }
        }

        await new Promise(r => setTimeout(r, 2000));
        const variantsInfo = (p.variants && p.variants.length > 0) ? p.variants.map((v, i) => `[${i+1}] ${v.name} (${v.grams}g, $${v.price})`).join(', ') : 'Ninguna';
        const prompt = `Analiza el siguiente producto:
Título: ${p.title}
Descripción original: ${p.description?.slice(0, 500)}
Variantes (nombre, peso, precio): ${variantsInfo}

${base64Image ? 'También te he adjuntado una imagen del producto físico final para que la analices.' : ''}

REGLA CRITICA DE NEGOCIO:
Tu eres una tienda online que vende el producto FISICO ya fabricado. 
El cliente final es un comprador normal, NO un maker. 
Por lo tanto, ESTA ESTRICTAMENTE PROHIBIDO mencionar terminos de impresion 3D como "facil de imprimir", "sin soportes", "STL", "filamento", "impresion", "A1 MINI", "perfil", etc. 
Describe el objeto enfocandote unicamente en su estetica, uso practico, decoracion o beneficio.

REGLA SOBRE COMPONENTES ELECTRONICOS:
Si notas que el producto es una carcasa, base, stand o estuche protector para componentes electronicos (como un ESP32, Raspberry Pi, placa, pantalla, Arduino, Alexa, etc.), debes ser EXTREMADAMENTE CLARO:
- Debes reescribir el titulo agregando al final "(Solo Carcasa)" o "(Solo Soporte)".
- En la descripcion debes aclarar: "Solo incluye las piezas impresas. NO incluye los componentes electronicos ni pantallas."

Devuelve un JSON valido con esta estructura exacta:
{
  "title": "Nuevo titulo comercial (dejalo igual si es normal, o agrega la aclaracion de 'Solo Carcasa' si es de electronica)",
  "description": "Una descripcion corta y atractiva (max 150 caracteres), sin mencionar su metodo de fabricacion.",
  "category": "Asigna una categoria comercial (ej. Hogar, Organizadores, Mascotas, Decoracion, Cosplay, Juguetes). Mantenla corta (max 2 palabras)",
  "hashtags": ["tag1", "tag2", "tag3"],
  "variants": ["Nombre 1", "Nombre 2"] // Obligatorio. Array de strings. Renombra las variantes actuales a nombres comerciales (ej. "Estandar", "Mini", "Grande", "Premium") basandote en su peso/precio. NUNCA uses terminos de 3D. El array debe tener el mismo numero de elementos que las variantes originales. Si dice 'Ninguna', devuelve un array vacio [].
}`;

        const parts = [{ text: prompt }];
        if (base64Image) {
            parts.push({
                inlineData: {
                    mimeType: mimeType,
                    data: base64Image
                }
            });
        }

        let response = null;
        let lastError = null;
        for (let attempt = 1; attempt <= 3; attempt++) {
            try {
                response = await this.helpers.httpRequest({
                    method: 'POST',
                    url: GEMINI_URL,
                    headers: { 'Content-Type': 'application/json' },
                    body: {
                        contents: [{ parts }]
                    }
                });
                break; // Éxito
            } catch (err) {
                lastError = err;
                if (attempt < 3) {
                    await new Promise(r => setTimeout(r, 4000)); // Esperar 4s antes de reintentar
                }
            }
        }
        if (!response) {
            throw lastError;
        }

        const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text || "";
        try {
            const jsonMatch = rawText.match(/\{.*\}/s);
            if (jsonMatch) {
                const aiData = JSON.parse(jsonMatch[0]);
                if (aiData.title) p.title = aiData.title;
                if (aiData.description) p.description = aiData.description;
                if (aiData.category) p.category = aiData.category;
                if (aiData.hashtags && Array.isArray(aiData.hashtags)) {
                    p.tags = aiData.hashtags;
                }
                if (aiData.variants && Array.isArray(aiData.variants) && p.variants && p.variants.length === aiData.variants.length) {
                    for (let j = 0; j < p.variants.length; j++) {
                        p.variants[j].name = aiData.variants[j];
                    }
                }
            } else {
                p.description = "DEBUG GEMINI (NO JSON): " + rawText.slice(0, 300);
            }
        } catch (parseErr) {
            p.description = "DEBUG GEMINI (JSON INVALIDO): " + parseErr.message + " | TEXTO RECIBIDO: " + rawText.slice(0, 300);
        }
    } catch (e) {
        let errStr = e.message || e.toString();
        try {
            if (e.response && e.response.data) errStr += " | Data: " + JSON.stringify(e.response.data);
            if (e.response && e.response.body) errStr += " | Body: " + (typeof e.response.body === "object" ? JSON.stringify(e.response.body) : e.response.body);
            if (e.error) errStr += " | ErrorObj: " + (typeof e.error === "object" ? JSON.stringify(e.error) : e.error);
        } catch(dumpErr) { errStr += " | DUMP FAILED: " + dumpErr.message; }
        p.description = "DEBUG GEMINI (ERROR CONEXION): " + errStr + " | URL: " + GEMINI_URL.replace(GEMINI_API_KEY.trim(), "[OCULTA]");
        console.log("Error al llamar a Gemini:", errStr);
    }
}

// Filtramos los productos que fallaron incluso despues de los reintentos
const finalProducts = products.filter(p => p.description && !p.description.startsWith("DEBUG GEMINI") && !p.description.startsWith("ERROR:"));
return [{ json: { products: finalProducts } }];
